result.output:
//! The platform-neutral driver contract every backend implements.
//!
//! All coordinates crossing this boundary are **device pixels** of the
//! captured display (the pixel grid of the screenshot the driver returned).
//! Backends that post input in other units (macOS points, Windows normalized
//! absolute coordinates) convert internally using the scale they reported in
//! [`TargetInfo`].

use std::fmt;

use crate::elements::ElementDriver;
use crate::keys::KeyCombo;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Button {
    Left,
    Right,
    Middle,
}

impl Button {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.to_ascii_lowercase().as_str() {
            "left" | "" => Ok(Self::Left),
            "right" => Ok(Self::Right),
            "middle" => Ok(Self::Middle),
            other => Err(format!(
                "unknown button `{other}`; expected left, right, or middle"
            )),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScrollDir {
    Up,
    Down,
    Left,
    Right,
}

impl ScrollDir {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.to_ascii_lowercase().as_str() {
            "up" => Ok(Self::Up),
            "down" => Ok(Self::Down),
            "left" => Ok(Self::Left),
            "right" => Ok(Self::Right),
            other => Err(format!(
                "unknown scroll direction `{other}`; expected up, down, left, or right"
            )),
        }
    }
}

/// A point in device pixels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TargetKind {
    Desktop,
    Android,
    Harmony,
}

impl TargetKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::Desktop => "desktop",
            Self::Android => "android",
            Self::Harmony => "harmony",
        }
    }
}

/// What the model is told about the target in `computer_info`.
#[derive(Debug, Clone)]
pub struct TargetInfo {
    pub kind: TargetKind,
    /// Human-readable backend name, e.g. `macos-coregraphics`, `adb`.
    pub driver: String,
    /// Captured display size in device pixels.
    pub device_w: u32,
    pub device_h: u32,
    /// Free-form diagnostics: permissions, helper binaries found, device id.
    pub notes: Vec<String>,
    pub supports_ui_tree: bool,
    pub supports_apps: bool,
}

/// An encoded screenshot straight from the backend (PNG or JPEG bytes).
#[derive(Debug, Clone)]
pub struct RawFrame {
    pub bytes: Vec<u8>,
}

/// One interactive element from an accessibility/layout dump.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UiNode {
    pub class: String,
    /// Visible text or content description.
    pub label: String,
    /// Resource id / component id when present.
    pub id: String,
    /// `(left, top, right, bottom)` in device pixels.
    pub bounds: (u32, u32, u32, u32),
    pub clickable: bool,
    pub scrollable: bool,
    pub editable: bool,
    pub focused: bool,
    pub depth: u8,
}

impl UiNode {
    pub fn center(&self) -> (u32, u32) {
        let (l, t, r, b) = self.bounds;
        ((l + r) / 2, (t + b) / 2)
    }

    pub fn is_interesting(&self) -> bool {
        self.clickable
            || self.scrollable
            || self.editable
            || self.focused
            || !self.label.trim().is_empty()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppAction<'a> {
    Launch(&'a str),
    List,
    Current,
}

#[derive(Debug)]
pub enum DriverError {
    /// The backend cannot do this on this target (e.g. UI tree on desktop).
    Unsupported(String),
    /// A helper binary or device is missing; message names the fix.
    Unavailable(String),
    /// The OS refused (permissions).
    Permission(String),
    /// Anything else, already phrased for the operator.
    Failed(String),
}

impl fmt::Display for DriverError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unsupported(m) => write!(f, "unsupported on this target: {m}"),
            Self::Unavailable(m) => write!(f, "unavailable: {m}"),
            Self::Permission(m) => write!(f, "permission denied: {m}"),
            Self::Failed(m) => write!(f, "{m}"),
        }
    }
}

impl std::error::Error for DriverError {}

impl DriverError {
    pub fn failed(msg: impl Into<String>) -> Self {
        Self::Failed(msg.into())
    }
}

pub trait Driver {
    fn info(&mut self) -> Result<TargetInfo, DriverError>;
    fn screenshot(&mut self) -> Result<RawFrame, DriverError>;
    fn move_to(&mut self, p: Point) -> Result<(), DriverError>;
    /// `clicks` is 1..=3; `hold_ms > 0` means press-and-hold (long press).
    fn click(
        &mut self,
        p: Point,
        button: Button,
        clicks: u32,
        hold_ms: u64,
    ) -> Result<(), DriverError>;
    fn drag(&mut self, from: Point, to: Point, duration_ms: u64) -> Result<(), DriverError>;
    /// `amount` is in notches (desktop) or roughly half-screens/5 (devices).
    fn scroll(&mut self, p: Point, dir: ScrollDir, amount: u32) -> Result<(), DriverError>;
    fn type_text(&mut self, text: &str) -> Result<(), DriverError>;
    fn key(&mut self, combo: &KeyCombo) -> Result<(), DriverError>;
    fn ui_tree(&mut self) -> Result<Vec<UiNode>, DriverError>;
    fn app(&mut self, action: AppAction<'_>) -> Result<String, DriverError>;
    fn devices(&mut self) -> Result<String, DriverError>;

    /// App/element-level control (phase 2). Desktop drivers that can address
    /// one app at a time return `Some(self)`; everyone else inherits `None`.
    fn element(&mut self) -> Option<&mut dyn ElementDriver> {
        None
    }
}

//! Element-level perception and action: the [`ElementDriver`] contract.
//!
//! Phase 1 speaks pixels to a whole screen; phase 2 speaks **apps and
//! elements**. An [`ElementDriver`] lists running apps, captures one
//! app/window at a time (image + indexed element tree), and acts on that
//! app without touching the user's cursor or foreground (where the platform
//! supports it — macOS). Platform support is reported per driver in
//! [`ElementCaps`]; the session translates gaps into actionable errors.

use crate::consent::AppIdentity;
use crate::driver::{Button, DriverError, ScrollDir};
use crate::keys::KeyCombo;

/// One window of an app as the directory reports it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WindowInfo {
    /// Platform window id (CGWindowID on macOS, HWND-derived on Windows).
    pub id: u32,
    pub title: String,
    /// Window frame in the platform's screen space (points on macOS,
    /// physical pixels elsewhere; drivers convert internally).
    pub x: i32,
    pub y: i32,
    pub w: u32,
    pub h: u32,
}

/// A running app and its windows.
#[derive(Debug, Clone, PartialEq)]
pub struct AppInfo {
    pub identity: AppIdentity,
    pub windows: Vec<WindowInfo>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum StateMode {
    /// Window image + indexed element tree.
    #[default]
    Full,
    /// Window image only.
    Image,
    /// Element tree only.
    Ax,
}

impl StateMode {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.trim().to_ascii_lowercase().as_str() {
            "" | "full" | "both" => Ok(Self::Full),
            "image" | "screenshot" | "pixels" => Ok(Self::Image),
            "ax" | "tree" | "elements" | "text" => Ok(Self::Ax),
            other => Err(format!(
                "unknown mode `{other}`; expected full, image, or ax"
            )),
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Full => "full",
            Self::Image => "image",
            Self::Ax => "ax",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct StateOpts {
    pub mode: StateMode,
    /// Case-insensitive substring filter over node text and roles.
    pub filter: Option<String>,
    /// Restrict capture to one window of the app.
    pub window_id: Option<u32>,
    /// Cap on reported interactive nodes.
    pub max_nodes: usize,
    /// Longest edge of the returned window image (0 = driver default).
    pub max_edge: u32,
}

/// One element in a captured window, in snapshot order.
#[derive(Debug, Clone, PartialEq)]
pub struct ElementNode {
    pub index: usize,
    /// Accessibility role or widget class ("AXButton", "Button").
    pub role: String,
    /// Title / value / description, whichever the element exposes.
    pub title: String,
    /// Frame in **window-image pixels** of the snapshot that listed it.
    pub x: u32,
    pub y: u32,
    pub w: u32,
    pub h: u32,
    /// Supported element actions ("press", "menu", "set_value", …).
    pub actions: Vec<String>,
    pub focused: bool,
    pub enabled: bool,
    /// Secure text field: never receives set_value/type.
    pub secure: bool,
    pub depth: u8,
}

impl ElementNode {
    pub fn is_interactive(&self) -> bool {
        !self.actions.is_empty()
            || self.focused
            || self.secure
            || matches!(
                self.role.as_str(),
                "AXTextField" | "AXTextArea" | "AXComboBox" | "TextField" | "EditText"
            )
    }

    pub fn center(&self) -> (f64, f64) {
        (
            f64::from(self.x) + f64::from(self.w) / 2.0,
            f64::from(self.y) + f64::from(self.h) / 2.0,
        )
    }
}

/// The result of `app_state`: one window as image + indexed tree.
#[derive(Debug, Clone)]
pub struct AppState {
    pub identity: AppIdentity,
    pub window: WindowInfo,
    /// PNG of the window, scaled to the model budget. Window-local pixels
    /// of this image are the coordinate space for background clicks.
    pub image_png: Option<Vec<u8>>,
    pub image_w: u32,
    pub image_h: u32,
    pub nodes: Vec<ElementNode>,
    /// Nodes hidden by the cap/filter (for the "N more omitted" line).
    pub omitted: usize,
    /// The window is fully covered by other windows (capture still works).
    pub occluded: bool,
}

/// What a driver can do with elements on this platform.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ElementCaps {
    /// Element tree capture is available.
    pub tree: bool,
    /// Window-scoped image capture is available.
    pub window_image: bool,
    /// Actions reach the app without foreground or cursor movement.
    pub background_actions: bool,
    /// Short note for `computer_info`.
    pub note: &'static str,
}

/// One action on one app. Coordinates are window-local in the platform's
/// native units (points on macOS), mapped by the session from the last
/// snapshot's image pixels.
#[derive(Debug, Clone, PartialEq)]
pub enum ElementAction {
    /// AXPress on the indexed element; falls back to a background click at
    /// its center.
    Press { index: usize },
    Click {
        x: f64,
        y: f64,
        button: Button,
        clicks: u32,
        hold_ms: u64,
    },
    /// Write `value` to the indexed element with read-back verification;
    /// text-field fallback is focus + select-all + type.
    SetValue { index: usize, value: String },
    Type {
        text: String,
    },
    Key {
        combo: KeyCombo,
    },
    /// Open the indexed element's menu (AXShowMenu / secondary action).
    Menu {
        index: usize,
    },
    /// Scroll by whole pages at the indexed element or a point; the receipt
    /// reports whether the window actually moved.
    Scroll {
        index: Option<usize>,
        point: Option<(f64, f64)>,
        dir: ScrollDir,
        pages: u32,
    },
    /// Select a character range in the indexed text element.
    SelectText {
        index: usize,
        start: usize,
        end: usize,
    },
    Drag {
        from: (f64, f64),
        to: (f64, f64),
        duration_ms: u64,
    },
}

/// What the driver observed after acting.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ActionReceipt {
    /// Operator phrasing: "pressed button \"OK\"".
    pub text: String,
    /// Read-back result for writes (Some(true) = value confirmed).
    pub verified: Option<bool>,
    /// Scroll movement detection (Some(false) = end of content).
    pub moved: Option<bool>,
}

/// The app-targeted half of a driver. Phase-1 [`crate::driver::Driver`]
/// stays for whole-screen/foreground work; desktop drivers that can address
/// apps implement both (exposed through
/// `Driver::element`), device drivers map element actions onto their UI
/// trees.
pub trait ElementDriver {
    /// Running apps with windows, in no particular order.
    fn apps(&mut self) -> Result<Vec<AppInfo>, DriverError>;

    /// Capture one window of `app` (image and/or indexed tree) and cache
    /// the snapshot so index-based actions can refer to it.
    fn app_state(&mut self, app: &AppIdentity, opts: &StateOpts) -> Result<AppState, DriverError>;

    /// Perform one action against `app`, using the last snapshot where an
    /// index is involved.
    fn act(&mut self, app: &AppIdentity, action: ElementAction) -> Result<ActionReceipt, DriverError>;

    /// Explicit, visible fallback: bring the app's window forward.
    fn raise(&mut self, app: &AppIdentity) -> Result<(), DriverError>;

    fn caps(&self) -> ElementCaps;
}

/// Render an element tree the way the model sees it: one line per
/// interactive node with a stable `#index`, role, title, and flags.
pub fn render_nodes(nodes: &[ElementNode], filter: Option<&str>, max: usize) -> (String, usize) {
    let mut lines = Vec::new();
    let mut shown = 0usize;
    let mut total = 0usize;
    for node in nodes {
        if !node.is_interactive() {
            continue;
        }
        if let Some(needle) = filter
            && !needle.is_empty()
        {
            let needle = needle.to_lowercase();
            let haystack = format!("{} {}", node.role, node.title).to_lowercase();
            if !haystack.contains(&needle) {
                continue;
            }
        }
        total += 1;
        if shown >= max {
            continue;
        }
        let mut flags: Vec<&str> = Vec::new();
        if node.focused {
            flags.push("focused");
        }
        if !node.enabled {
            flags.push("disabled");
        }
        if node.secure {
            flags.push("secure");
        }
        let title = if node.title.is_empty() {
            String::new()
        } else {
            let trimmed: String = node.title.chars().take(80).collect();
            format!(" \"{}\"", trimmed.replace('\n', "\\n"))
        };
        let acts = if node.actions.is_empty() {
            String::new()
        } else {
            format!(" {}", node.actions.join(","))
        };
        let flag_text = if flags.is_empty() {
            String::new()
        } else {
            format!(" {}", flags.join(","))
        };
        lines.push(format!(
            "#{index} [{role}]{title} at ({x},{y} {w}x{h}){flag_text}{acts}",
            index = node.index,
            role = node.role,
            x = node.x,
            y = node.y,
            w = node.w,
            h = node.h,
        ));
        shown += 1;
    }
    (lines.join("\n"), total)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn node(index: usize, role: &str, title: &str, actions: &[&str]) -> ElementNode {
        ElementNode {
            index,
            role: role.into(),
            title: title.into(),
            x: index as u32 * 10,
            y: 5,
            w: 80,
            h: 20,
            actions: actions.iter().map(|s| s.to_string()).collect(),
            focused: false,
            enabled: true,
            secure: false,
            depth: 2,
        }
    }

    #[test]
    fn mode_parsing() {
        assert_eq!(StateMode::parse("full").unwrap(), StateMode::Full);
        assert_eq!(StateMode::parse("IMAGE").unwrap(), StateMode::Image);
        assert_eq!(StateMode::parse("tree").unwrap(), StateMode::Ax);
        assert_eq!(StateMode::parse("").unwrap(), StateMode::Full);
        assert!(StateMode::parse("soup").is_err());
    }

    #[test]
    fn render_lists_interactive_nodes_only_with_cap() {
        let nodes = vec![
            node(0, "AXWindow", "Main", &[]),
            node(1, "AXButton", "OK", &["press"]),
            node(2, "AXTextField", "search", &[]),
            node(3, "AXButton", "Cancel", &["press"]),
        ];
        let (text, total) = render_nodes(&nodes, None, 2);
        assert_eq!(total, 3);
        assert!(text.contains("#1 [AXButton] \"OK\""));
        assert!(text.contains("#2 [AXTextField] \"search\""));
        assert!(!text.contains("Cancel"), "cap of 2 nodes");
        assert!(!text.contains("AXWindow"), "non-interactive hidden");
    }

    #[test]
    fn render_filters_case_insensitively() {
        let nodes = vec![
            node(0, "AXButton", "Save Draft", &["press"]),
            node(1, "AXButton", "Delete", &["press"]),
        ];
        let (text, total) = render_nodes(&nodes, Some("save"), 10);
        assert_eq!(total, 1);
        assert!(text.contains("Save Draft"));
        assert!(!text.contains("Delete"));
    }

    #[test]
    fn secure_fields_are_interactive_but_flagged() {
        let mut node = node(0, "AXSecureTextField", "", &[]);
        node.secure = true;
        assert!(node.is_interactive());
        let (text, _) = render_nodes(&[node], None, 10);
        assert!(text.contains("secure"));
    }

    #[test]
    fn center_math() {
        let node = node(0, "AXButton", "", &[]);
        let (cx, cy) = node.center();
        assert_eq!((cx, cy), (40.0, 15.0));
    }
}

//! Per-app consent for computer use (Codex-style, enforced server-side).
//!
//! Three verdicts shape every app-targeted call: hard exclusions always win
//! (`Excluded`), the `[apps] deny` list beats the allow list (`Denied`), the
//! allow list grants access (`Allowed`), and anything unmatched asks the
//! user (`NeedsApproval`). MCP tool approval still stands in front of every
//! call; this is the additional, durable, per-target gate.

/// Apps the agent may never target, not configurable. Security surfaces and
/// Codewhale's own processes; the terminal that hosts Codewhale is added at
/// runtime (see [`Policy::with_host_terminal`]).
pub const HARD_EXCLUDED_BUNDLE_IDS: &[&str] = &[
    "com.apple.securityagent",
    "com.apple.loginwindow",
    "com.apple.systempreferences",
    "com.apple.systemuiserver",
    "com.apple.terminal",
];

pub const HARD_EXCLUDED_PROCESS_NAMES: &[&str] = &[
    "SecurityAgent",
    "SecurityAgentService",
    "loginwindow",
    "System Preferences",
    "System Settings",
    "codewhale",
    "codew",
    "codewhale-computer-use",
];

/// One app as the consent model sees it.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct AppIdentity {
    pub pid: u32,
    /// Localized display name, e.g. "Notes".
    pub name: String,
    /// Reverse-DNS bundle id ("com.apple.Notes"), Android package, or
    /// HarmonyOS bundle name. Empty when the platform has none.
    pub bundle_id: String,
    /// Host process name (macOS/Linux/Windows); empty on devices.
    pub process_name: String,
}

impl AppIdentity {
    /// All names this app answers to, for policy matching and messages.
    pub fn aliases(&self) -> Vec<String> {
        let mut out = Vec::new();
        for alias in [&self.bundle_id, &self.name, &self.process_name] {
            let trimmed = alias.trim();
            if !trimmed.is_empty()
                && !out.iter().any(|existing: &String| existing.eq_ignore_ascii_case(trimmed))
            {
                out.push(trimmed.to_string());
            }
        }
        out
    }

    /// The best human label for messages.
    pub fn label(&self) -> String {
        if !self.name.trim().is_empty() {
            self.name.trim().to_string()
        } else if !self.process_name.trim().is_empty() {
            self.process_name.trim().to_string()
        } else if !self.bundle_id.trim().is_empty() {
            self.bundle_id.trim().to_string()
        } else {
            format!("pid {}", self.pid)
        }
    }
}

/// The `[apps]` policy from `computer-use.toml`, plus the detected host
/// terminal.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Policy {
    pub allow: Vec<String>,
    pub deny: Vec<String>,
    /// Process name / bundle id of the terminal app hosting Codewhale.
    pub host_terminal: Option<String>,
    /// Pid of the terminal app hosting Codewhale, detected at runtime.
    pub host_terminal_pid: Option<u32>,
}

impl Policy {
    /// True when the identity names a hard-excluded app or the host
    /// terminal.
    pub fn is_excluded(&self, app: &AppIdentity) -> bool {
        if let Some(pid) = self.host_terminal_pid
            && app.pid == pid
        {
            return true;
        }
        let aliases = app.aliases();
        let matches = |candidate: &str| {
            aliases
                .iter()
                .any(|alias| alias.eq_ignore_ascii_case(candidate))
        };
        if HARD_EXCLUDED_BUNDLE_IDS.iter().any(|id| matches(id)) {
            return true;
        }
        if HARD_EXCLUDED_PROCESS_NAMES.iter().any(|name| matches(name)) {
            return true;
        }
        if let Some(terminal) = &self.host_terminal
            && !terminal.trim().is_empty()
            && matches(terminal)
        {
            return true;
        }
        false
    }

    pub fn verdict(&self, app: &AppIdentity) -> Verdict {
        if self.is_excluded(app) {
            return Verdict::Excluded;
        }
        let aliases = app.aliases();
        let listed = |list: &[String]| {
            list.iter().any(|entry| {
                let entry = entry.trim();
                !entry.is_empty() && aliases.iter().any(|a| a.eq_ignore_ascii_case(entry))
            })
        };
        if listed(&self.deny) {
            return Verdict::Denied;
        }
        if listed(&self.allow) {
            Verdict::Allowed
        } else {
            Verdict::NeedsApproval
        }
    }

    /// The `[apps]` entries currently granted for status listings.
    pub fn allow_line(&self) -> String {
        toml_list(&self.allow)
    }

    pub fn deny_line(&self) -> String {
        toml_list(&self.deny)
    }
}

/// The outcome of a consent check for one app.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    Allowed,
    NeedsApproval,
    Denied,
    Excluded,
}

/// The structured approval error the `/computer` command turns into a
/// question to the user.
pub fn needs_approval_error(app: &AppIdentity, path_hint: &str) -> String {
    let entry = if app.bundle_id.trim().is_empty() {
        app.label()
    } else {
        app.bundle_id.trim().to_string()
    };
    format!(
        "needs_app_approval: `{}` is not allowed for computer use yet.\nAsk the user; if they agree, add this line to {} under [apps]:\n  allow = [\"{}\"]\n(or deny it with deny = [\"{}\"]). Computer-use actions stay disabled for this app until then.",
        app.label(),
        path_hint,
        entry,
        entry
    )
}

pub fn excluded_error(app: &AppIdentity) -> String {
    format!(
        "`{}` can never be targeted: security, login, and system-settings surfaces and Codewhale's own processes are hard-excluded from computer use",
        app.label()
    )
}

pub fn denied_error(app: &AppIdentity) -> String {
    format!(
        "`{}` is on the deny list in [apps]; remove it from deny to target this app",
        app.label()
    )
}

fn toml_list(items: &[String]) -> String {
    if items.is_empty() {
        "[]".to_string()
    } else {
        format!(
            "[{}]",
            items
                .iter()
                .map(|item| format!("\"{}\"", item.trim()))
                .collect::<Vec<_>>()
                .join(", ")
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn app(name: &str, bundle: &str) -> AppIdentity {
        AppIdentity {
            pid: 100,
            name: name.into(),
            bundle_id: bundle.into(),
            process_name: name.into(),
        }
    }

    #[test]
    fn unlisted_apps_need_approval() {
        let policy = Policy::default();
        assert_eq!(policy.verdict(&app("Notes", "com.apple.Notes")), Verdict::NeedsApproval);
        let message = needs_approval_error(&app("Notes", "com.apple.Notes"), "~/.codewhale/computer-use.toml");
        assert!(message.starts_with("needs_app_approval:"));
        assert!(message.contains("allow = [\"com.apple.Notes\"]"));
    }

    #[test]
    fn allow_matches_bundle_name_or_process_case_insensitively() {
        let mut policy = Policy::default();
        policy.allow = vec!["com.apple.notes".into()];
        assert_eq!(policy.verdict(&app("Notes", "com.apple.Notes")), Verdict::Allowed);
        let mut policy = Policy::default();
        policy.allow = vec!["CALCULATOR".into()];
        assert_eq!(
            policy.verdict(&app("Calculator", "com.apple.calculator")),
            Verdict::Allowed
        );
    }

    #[test]
    fn deny_beats_allow() {
        let mut policy = Policy::default();
        policy.allow = vec!["Notes".into()];
        policy.deny = vec!["com.apple.Notes".into()];
        assert_eq!(policy.verdict(&app("Notes", "com.apple.Notes")), Verdict::Denied);
    }

    #[test]
    fn hard_exclusions_win_over_allow() {
        let mut policy = Policy::default();
        policy.allow = vec!["com.apple.securityagent".into(), "System Settings".into()];
        assert_eq!(
            policy.verdict(&app("SecurityAgent", "com.apple.securityagent")),
            Verdict::Excluded
        );
        assert_eq!(
            policy.verdict(&app("System Settings", "com.apple.systemsettings")),
            Verdict::Excluded
        );
        assert_eq!(
            policy.verdict(&app("Codewhale", "com.codewhale.cli")),
            Verdict::Excluded
        );
    }

    #[test]
    fn host_terminal_is_excluded() {
        let mut policy = Policy::default();
        policy.host_terminal = Some("WezTerm".into());
        policy.allow = vec!["WezTerm".into()];
        assert_eq!(policy.verdict(&app("WezTerm", "com.github.wez.wezterm")), Verdict::Excluded);
        assert_eq!(policy.verdict(&app("Notes", "com.apple.Notes")), Verdict::NeedsApproval);
    }

    #[test]
    fn host_terminal_pid_wins_even_when_renamed() {
        let mut policy = Policy::default();
        policy.host_terminal_pid = Some(100);
        policy.allow = vec!["Anything".into()];
        assert_eq!(policy.verdict(&app("Anything", "com.x.y")), Verdict::Excluded);
    }

    #[test]
    fn aliases_and_labels() {
        let app = app("Notes", "com.apple.Notes");
        assert_eq!(app.aliases().len(), 2);
        assert_eq!(app.label(), "Notes");
        let pid_only = AppIdentity { pid: 7, ..Default::default() };
        assert_eq!(pid_only.label(), "pid 7");
        assert!(pid_only.aliases().is_empty());
    }
}

//! macOS driver: `screencapture` for pixels, CoreGraphics events for input.
//!
//! No crates: the handful of CoreGraphics/ApplicationServices symbols are
//! declared here. Mouse and keyboard events are posted at the HID tap in
//! display points; the driver converts from device pixels using the
//! backing scale of the main display.
//!
//! Permissions: Screen Recording (for `screencapture`) and Accessibility
//! (for posting events) must be granted to the terminal app that runs
//! Codewhale.

use std::ffi::c_void;
use std::time::Duration;

use crate::driver::{
    AppAction, Button, Driver, DriverError, Point, RawFrame, ScrollDir, TargetInfo, TargetKind,
    UiNode,
};
use crate::keys::{Key, KeyCombo, NamedKey};
use crate::process;

#[repr(C)]
#[derive(Clone, Copy)]
struct CGPoint {
    x: f64,
    y: f64,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct CGSize {
    width: f64,
    height: f64,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct CGRect {
    origin: CGPoint,
    size: CGSize,
}

type CGEventRef = *mut c_void;
type CGEventSourceRef = *mut c_void;

const K_CG_HID_EVENT_TAP: u32 = 0;
const K_CG_EVENT_LEFT_MOUSE_DOWN: u32 = 1;
const K_CG_EVENT_LEFT_MOUSE_UP: u32 = 2;
const K_CG_EVENT_RIGHT_MOUSE_DOWN: u32 = 3;
const K_CG_EVENT_RIGHT_MOUSE_UP: u32 = 4;
const K_CG_EVENT_MOUSE_MOVED: u32 = 5;
const K_CG_EVENT_LEFT_MOUSE_DRAGGED: u32 = 6;
const K_CG_EVENT_OTHER_MOUSE_DOWN: u32 = 25;
const K_CG_EVENT_OTHER_MOUSE_UP: u32 = 26;
const K_CG_MOUSE_BUTTON_LEFT: u32 = 0;
const K_CG_MOUSE_BUTTON_RIGHT: u32 = 1;
const K_CG_MOUSE_BUTTON_CENTER: u32 = 2;
const K_CG_MOUSE_EVENT_CLICK_STATE: u32 = 1;
const K_CG_SCROLL_EVENT_UNIT_LINE: u32 = 1;
const FLAG_SHIFT: u64 = 1 << 17;
const FLAG_CONTROL: u64 = 1 << 18;
const FLAG_ALTERNATE: u64 = 1 << 19;
const FLAG_COMMAND: u64 = 1 << 20;

#[link(name = "CoreGraphics", kind = "framework")]
unsafe extern "C" {
    fn CGMainDisplayID() -> u32;
    fn CGDisplayBounds(display: u32) -> CGRect;
    fn CGDisplayCopyDisplayMode(display: u32) -> *mut c_void;
    fn CGDisplayModeGetPixelWidth(mode: *const c_void) -> usize;
    fn CGDisplayModeGetPixelHeight(mode: *const c_void) -> usize;
    fn CGDisplayModeRelease(mode: *mut c_void);
    fn CGEventCreateMouseEvent(
        source: CGEventSourceRef,
        mouse_type: u32,
        point: CGPoint,
        button: u32,
    ) -> CGEventRef;
    fn CGEventCreateKeyboardEvent(
        source: CGEventSourceRef,
        keycode: u16,
        keydown: bool,
    ) -> CGEventRef;
    fn CGEventCreateScrollWheelEvent2(
        source: CGEventSourceRef,
        units: u32,
        wheel_count: u32,
        wheel1: i32,
        wheel2: i32,
        wheel3: i32,
    ) -> CGEventRef;
    fn CGEventSetIntegerValueField(event: CGEventRef, field: u32, value: i64);
    fn CGEventSetFlags(event: CGEventRef, flags: u64);
    fn CGEventKeyboardSetUnicodeString(event: CGEventRef, length: usize, string: *const u16);
    fn CGEventPost(tap: u32, event: CGEventRef);
    fn CGPreflightScreenCaptureAccess() -> bool;
    fn CGRequestScreenCaptureAccess() -> bool;
}

#[link(name = "CoreFoundation", kind = "framework")]
unsafe extern "C" {
    static kCFTypeDictionaryKeyCallBacks: u8;
    static kCFTypeDictionaryValueCallBacks: u8;
    static kCFBooleanTrue: *const c_void;
    fn CFDictionaryCreate(
        allocator: *const c_void,
        keys: *const *const c_void,
        values: *const *const c_void,
        count: isize,
        key_callbacks: *const c_void,
        value_callbacks: *const c_void,
    ) -> *const c_void;
}

#[link(name = "ApplicationServices", kind = "framework")]
unsafe extern "C" {
    static kAXTrustedCheckOptionPrompt: *const c_void;
    fn AXIsProcessTrustedWithOptions(options: *const c_void) -> bool;
}

/// Current permission state: `(accessibility, screen_recording)`.
pub fn permission_status() -> (bool, bool) {
    // SAFETY: no preconditions.
    unsafe { (AXIsProcessTrusted(), CGPreflightScreenCaptureAccess()) }
}

/// Ask macOS to show the Accessibility and Screen Recording prompts for the
/// current process (the terminal app) and return the resulting state. macOS
/// only adds the app to the list; the user still flips the toggles.
pub fn request_permissions() -> (bool, bool) {
    // SAFETY: builds a one-entry CFDictionary {kAXTrustedCheckOptionPrompt: true}
    // from valid CoreFoundation constants and releases it afterwards.
    let accessibility = unsafe {
        let keys = [kAXTrustedCheckOptionPrompt];
        let values = [kCFBooleanTrue];
        let options = CFDictionaryCreate(
            std::ptr::null(),
            keys.as_ptr(),
            values.as_ptr(),
            1,
            &kCFTypeDictionaryKeyCallBacks as *const u8 as *const c_void,
            &kCFTypeDictionaryValueCallBacks as *const u8 as *const c_void,
        );
        let trusted = AXIsProcessTrustedWithOptions(options);
        if !options.is_null() {
            CFRelease(options);
        }
        trusted
    };
    // SAFETY: no preconditions.
    let screen = unsafe { CGRequestScreenCaptureAccess() };
    (accessibility, screen)
}

#[link(name = "CoreFoundation", kind = "framework")]
unsafe extern "C" {
    fn CFRelease(cf: *const c_void);
}

/// The shared `kCFBooleanTrue` constant, usable as an AX attribute value.
pub(crate) fn cf_boolean_true() -> *mut c_void {
    // SAFETY: kCFBooleanTrue is a global CF constant; borrowing is fine.
    unsafe { kCFBooleanTrue as *mut c_void }
}

#[link(name = "ApplicationServices", kind = "framework")]
unsafe extern "C" {
    fn AXIsProcessTrusted() -> bool;
}

fn post(event: CGEventRef) -> Result<(), DriverError> {
    if event.is_null() {
        return Err(DriverError::Failed(
            "CoreGraphics refused to create the event".to_string(),
        ));
    }
    // SAFETY: `event` is a valid CGEvent we own; post then release.
    unsafe {
        CGEventPost(K_CG_HID_EVENT_TAP, event);
        CFRelease(event);
    }
    Ok(())
}

fn post_with_flags(event: CGEventRef, flags: u64) -> Result<(), DriverError> {
    if event.is_null() {
        return Err(DriverError::Failed(
            "CoreGraphics refused to create the event".to_string(),
        ));
    }
    // SAFETY: event is valid and owned.
    unsafe {
        if flags != 0 {
            CGEventSetFlags(event, flags);
        }
    }
    post(event)
}

pub struct MacDriver {
    display: u32,
    logical_w: f64,
    logical_h: f64,
    pixel_w: u32,
    pixel_h: u32,
    pub(crate) element_snapshot: Option<crate::drivers::macos_ax::MacElementSnapshot>,
}

impl MacDriver {
    pub fn new() -> Result<Self, DriverError> {
        // SAFETY: plain CoreGraphics queries; the display mode is released.
        let (display, bounds, pw, ph) = unsafe {
            let display = CGMainDisplayID();
            let bounds = CGDisplayBounds(display);
            // In HiDPI ("looks like") modes CGDisplayPixelsWide reports
            // points; the display mode carries the real backing size that
            // `screencapture` produces.
            let mode = CGDisplayCopyDisplayMode(display);
            let (pw, ph) = if mode.is_null() {
                (bounds.size.width as usize, bounds.size.height as usize)
            } else {
                let dims = (
                    CGDisplayModeGetPixelWidth(mode),
                    CGDisplayModeGetPixelHeight(mode),
                );
                CGDisplayModeRelease(mode);
                dims
            };
            (display, bounds, pw, ph)
        };
        Ok(Self {
            display,
            logical_w: bounds.size.width,
            logical_h: bounds.size.height,
            pixel_w: pw as u32,
            pixel_h: ph as u32,
            element_snapshot: None,
        })
    }

    fn scale(&self) -> f64 {
        if self.logical_w > 0.0 {
            f64::from(self.pixel_w) / self.logical_w
        } else {
            1.0
        }
    }

    /// Backing scale exposed to the element backend.
    pub(crate) fn backing_scale(&self) -> f64 {
        self.scale()
    }

    pub(crate) fn display_id(&self) -> u32 {
        self.display
    }

    fn to_points(&self, p: Point) -> CGPoint {
        let s = self.scale();
        CGPoint {
            x: (p.x / s).clamp(0.0, (self.logical_w - 1.0).max(0.0)),
            y: (p.y / s).clamp(0.0, (self.logical_h - 1.0).max(0.0)),
        }
    }

    fn accessibility_ok() -> bool {
        // SAFETY: no preconditions.
        unsafe { AXIsProcessTrusted() }
    }

    fn require_accessibility() -> Result<(), DriverError> {
        if Self::accessibility_ok() {
            Ok(())
        } else {
            Err(DriverError::Permission(
                "Accessibility is not granted: open System Settings → Privacy & Security → Accessibility and enable the terminal app running Codewhale, then restart it".to_string(),
            ))
        }
    }

    pub(crate) fn accessibility_granted() -> bool {
        Self::accessibility_ok()
    }

    pub(crate) fn need_accessibility() -> Result<(), DriverError> {
        Self::require_accessibility()
    }

    fn mouse(
        &self,
        kind: u32,
        p: CGPoint,
        button: u32,
        click_state: i64,
        flags: u64,
    ) -> Result<(), DriverError> {
        // SAFETY: creating an event with valid arguments; ownership handled in post.
        let event = unsafe { CGEventCreateMouseEvent(std::ptr::null_mut(), kind, p, button) };
        if event.is_null() {
            return Err(DriverError::Failed(
                "CGEventCreateMouseEvent returned null".to_string(),
            ));
        }
        if click_state > 0 {
            // SAFETY: event is valid.
            unsafe {
                CGEventSetIntegerValueField(event, K_CG_MOUSE_EVENT_CLICK_STATE, click_state)
            };
        }
        post_with_flags(event, flags)
    }

    fn key_event(keycode: u16, down: bool, flags: u64) -> Result<(), DriverError> {
        // SAFETY: valid arguments.
        let event = unsafe { CGEventCreateKeyboardEvent(std::ptr::null_mut(), keycode, down) };
        post_with_flags(event, flags)
    }

    fn type_unicode(chunk: &[u16]) -> Result<(), DriverError> {
        for down in [true, false] {
            // SAFETY: valid arguments; the UTF-16 buffer outlives the call.
            let event = unsafe { CGEventCreateKeyboardEvent(std::ptr::null_mut(), 0, down) };
            if event.is_null() {
                return Err(DriverError::Failed(
                    "CGEventCreateKeyboardEvent returned null".to_string(),
                ));
            }
            unsafe { CGEventKeyboardSetUnicodeString(event, chunk.len(), chunk.as_ptr()) };
            post(event)?;
        }
        Ok(())
    }
}

pub(crate) fn modifier_flags(combo: &KeyCombo, extra_shift: bool) -> u64 {
    let mut flags = 0;
    if combo.modifiers.ctrl {
        flags |= FLAG_CONTROL;
    }
    if combo.modifiers.alt {
        flags |= FLAG_ALTERNATE;
    }
    if combo.modifiers.shift || extra_shift {
        flags |= FLAG_SHIFT;
    }
    if combo.modifiers.meta {
        flags |= FLAG_COMMAND;
    }
    flags
}

/// US-layout virtual key codes. Returns `(keycode, needs_shift)`.
pub(crate) fn keycode(key: &Key) -> Result<(u16, bool), DriverError> {
    Ok(match key {
        Key::Named(named) => (
            match named {
                NamedKey::Enter => 36,
                NamedKey::Tab => 48,
                NamedKey::Escape => 53,
                NamedKey::Backspace => 51,
                NamedKey::Delete => 117,
                NamedKey::Space => 49,
                NamedKey::Up => 126,
                NamedKey::Down => 125,
                NamedKey::Left => 123,
                NamedKey::Right => 124,
                NamedKey::Home => 115,
                NamedKey::End => 119,
                NamedKey::PageUp => 116,
                NamedKey::PageDown => 121,
                NamedKey::Insert => 114,
                NamedKey::CapsLock => 57,
                NamedKey::F(n) => match n {
                    1 => 122,
                    2 => 120,
                    3 => 99,
                    4 => 118,
                    5 => 96,
                    6 => 97,
                    7 => 98,
                    8 => 100,
                    9 => 101,
                    10 => 109,
                    11 => 103,
                    12 => 111,
                    13 => 105,
                    14 => 107,
                    15 => 113,
                    16 => 106,
                    17 => 64,
                    18 => 79,
                    19 => 80,
                    20 => 90,
                    _ => return Err(DriverError::Failed(format!("F{n} has no macOS key code"))),
                },
                NamedKey::Back
                | NamedKey::AppHome
                | NamedKey::Recents
                | NamedKey::Power
                | NamedKey::Menu => {
                    return Err(DriverError::Unsupported(format!(
                        "{named:?} is a phone key; use cmd/ctrl shortcuts on macOS"
                    )));
                }
                NamedKey::VolumeUp => 72,
                NamedKey::VolumeDown => 73,
            },
            false,
        ),
        Key::Char(c) => {
            let lower = c.to_ascii_lowercase();
            let shifted_symbols: &[(char, char)] = &[
                ('~', '`'),
                ('!', '1'),
                ('@', '2'),
                ('#', '3'),
                ('$', '4'),
                ('%', '5'),
                ('^', '6'),
                ('&', '7'),
                ('*', '8'),
                ('(', '9'),
                (')', '0'),
                ('_', '-'),
                ('+', '='),
                ('{', '['),
                ('}', ']'),
                ('|', '\\'),
                (':', ';'),
                ('"', '\''),
                ('<', ','),
                ('>', '.'),
                ('?', '/'),
            ];
            let (base, shift) = if c.is_ascii_uppercase() {
                (lower, true)
            } else if let Some((_, b)) = shifted_symbols.iter().find(|(s, _)| *s == *c) {
                (*b, true)
            } else {
                (*c, false)
            };
            let code: u16 = match base {
                'a' => 0,
                's' => 1,
                'd' => 2,
                'f' => 3,
                'h' => 4,
                'g' => 5,
                'z' => 6,
                'x' => 7,
                'c' => 8,
                'v' => 9,
                'b' => 11,
                'q' => 12,
                'w' => 13,
                'e' => 14,
                'r' => 15,
                'y' => 16,
                't' => 17,
                '1' => 18,
                '2' => 19,
                '3' => 20,
                '4' => 21,
                '6' => 22,
                '5' => 23,
                '=' => 24,
                '9' => 25,
                '7' => 26,
                '-' => 27,
                '8' => 28,
                '0' => 29,
                ']' => 30,
                'o' => 31,
                'u' => 32,
                '[' => 33,
                'i' => 34,
                'p' => 35,
                'l' => 37,
                'j' => 38,
                '\'' => 39,
                'k' => 40,
                ';' => 41,
                '\\' => 42,
                ',' => 43,
                '/' => 44,
                'n' => 45,
                'm' => 46,
                '.' => 47,
                '`' => 50,
                ' ' => 49,
                '\n' => 36,
                '\t' => 48,
                other => {
                    return Err(DriverError::Failed(format!(
                        "no macOS key code for `{other}`; use computer_type"
                    )));
                }
            };
            (code, shift)
        }
    })
}

impl Driver for MacDriver {
    fn info(&mut self) -> Result<TargetInfo, DriverError> {
        // SAFETY: no preconditions.
        let screen_ok = unsafe { CGPreflightScreenCaptureAccess() };
        let mut notes = vec![
            format!(
                "display: id {} {}x{} points, backing scale {:.2}",
                self.display,
                self.logical_w,
                self.logical_h,
                self.scale()
            ),
            format!(
                "screen recording permission: {}",
                if screen_ok {
                    "granted"
                } else {
                    "NOT granted (System Settings → Privacy & Security → Screen Recording → enable your terminal app)"
                }
            ),
            format!(
                "accessibility permission: {}",
                if Self::accessibility_ok() {
                    "granted"
                } else {
                    "NOT granted (System Settings → Privacy & Security → Accessibility → enable your terminal app)"
                }
            ),
        ];
        if !screen_ok {
            notes.push(
                "screenshots may come back blank/desktop-only until Screen Recording is granted"
                    .to_string(),
            );
        }
        Ok(TargetInfo {
            kind: TargetKind::Desktop,
            driver: "macos-coregraphics".into(),
            device_w: self.pixel_w,
            device_h: self.pixel_h,
            notes,
            supports_ui_tree: false,
            supports_apps: true,
        })
    }

    fn screenshot(&mut self) -> Result<RawFrame, DriverError> {
        let screencapture = process::which("screencapture")
            .unwrap_or_else(|| std::path::PathBuf::from("/usr/sbin/screencapture"));
        let path = std::env::temp_dir().join(format!("codewhale-cu-{}.png", std::process::id()));
        let path_str = path.to_string_lossy().into_owned();
        let _ = std::fs::remove_file(&path);
        let out = process::run(
            &screencapture,
            // `-m` captures only the main display: the point/pixel geometry
            // above is the main display's, and multi-monitor captures would
            // otherwise write one file per screen.
            &["-x", "-C", "-m", "-t", "png", &path_str],
            Duration::from_secs(20),
        )?;
        if !out.success() {
            let _ = std::fs::remove_file(&path);
            return Err(DriverError::Failed(format!(
                "screencapture failed (status {:?}): {}",
                out.status,
                process::tail(&out.stderr, 300)
            )));
        }
        let bytes = std::fs::read(&path)
            .map_err(|e| DriverError::Failed(format!("screenshot file missing: {e}")))?;
        let _ = std::fs::remove_file(&path);
        let img = crate::frame::decode(&bytes).map_err(DriverError::Failed)?;
        use image::GenericImageView;
        let (w, h) = img.dimensions();
        // Multi-display setups can put a different display first; keep the
        // geometry consistent with what we actually captured.
        self.pixel_w = w;
        self.pixel_h = h;
        Ok(RawFrame { bytes })
    }

    fn move_to(&mut self, p: Point) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        let pt = self.to_points(p);
        self.mouse(K_CG_EVENT_MOUSE_MOVED, pt, K_CG_MOUSE_BUTTON_LEFT, 0, 0)
    }

    fn click(
        &mut self,
        p: Point,
        button: Button,
        clicks: u32,
        hold_ms: u64,
    ) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        let pt = self.to_points(p);
        self.mouse(K_CG_EVENT_MOUSE_MOVED, pt, K_CG_MOUSE_BUTTON_LEFT, 0, 0)?;
        std::thread::sleep(Duration::from_millis(30));
        let (down, up, btn) = match button {
            Button::Left => (
                K_CG_EVENT_LEFT_MOUSE_DOWN,
                K_CG_EVENT_LEFT_MOUSE_UP,
                K_CG_MOUSE_BUTTON_LEFT,
            ),
            Button::Right => (
                K_CG_EVENT_RIGHT_MOUSE_DOWN,
                K_CG_EVENT_RIGHT_MOUSE_UP,
                K_CG_MOUSE_BUTTON_RIGHT,
            ),
            Button::Middle => (
                K_CG_EVENT_OTHER_MOUSE_DOWN,
                K_CG_EVENT_OTHER_MOUSE_UP,
                K_CG_MOUSE_BUTTON_CENTER,
            ),
        };
        if hold_ms > 0 {
            self.mouse(down, pt, btn, 1, 0)?;
            std::thread::sleep(Duration::from_millis(hold_ms));
            return self.mouse(up, pt, btn, 1, 0);
        }
        for n in 1..=i64::from(clicks.max(1)) {
            self.mouse(down, pt, btn, n, 0)?;
            self.mouse(up, pt, btn, n, 0)?;
            if n < i64::from(clicks) {
                std::thread::sleep(Duration::from_millis(60));
            }
        }
        Ok(())
    }

    fn drag(&mut self, from: Point, to: Point, duration_ms: u64) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        let start = self.to_points(from);
        let end = self.to_points(to);
        self.mouse(K_CG_EVENT_MOUSE_MOVED, start, K_CG_MOUSE_BUTTON_LEFT, 0, 0)?;
        std::thread::sleep(Duration::from_millis(30));
        self.mouse(
            K_CG_EVENT_LEFT_MOUSE_DOWN,
            start,
            K_CG_MOUSE_BUTTON_LEFT,
            1,
            0,
        )?;
        let steps = 20u64;
        let pause = duration_ms / steps;
        for i in 1..=steps {
            let f = i as f64 / steps as f64;
            let pt = CGPoint {
                x: start.x + (end.x - start.x) * f,
                y: start.y + (end.y - start.y) * f,
            };
            self.mouse(
                K_CG_EVENT_LEFT_MOUSE_DRAGGED,
                pt,
                K_CG_MOUSE_BUTTON_LEFT,
                1,
                0,
            )?;
            std::thread::sleep(Duration::from_millis(pause.max(5)));
        }
        self.mouse(K_CG_EVENT_LEFT_MOUSE_UP, end, K_CG_MOUSE_BUTTON_LEFT, 1, 0)
    }

    fn scroll(&mut self, p: Point, dir: ScrollDir, amount: u32) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        let pt = self.to_points(p);
        self.mouse(K_CG_EVENT_MOUSE_MOVED, pt, K_CG_MOUSE_BUTTON_LEFT, 0, 0)?;
        let n = i32::try_from(amount.max(1)).unwrap_or(i32::MAX);
        let (dy, dx) = match dir {
            ScrollDir::Up => (n, 0),
            ScrollDir::Down => (-n, 0),
            ScrollDir::Left => (0, n),
            ScrollDir::Right => (0, -n),
        };
        // SAFETY: valid arguments.
        let event = unsafe {
            CGEventCreateScrollWheelEvent2(
                std::ptr::null_mut(),
                K_CG_SCROLL_EVENT_UNIT_LINE,
                2,
                dy,
                dx,
                0,
            )
        };
        post(event)
    }

    fn type_text(&mut self, text: &str) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        for (i, segment) in text.split('\n').enumerate() {
            if i > 0 {
                Self::key_event(36, true, 0)?;
                Self::key_event(36, false, 0)?;
                std::thread::sleep(Duration::from_millis(15));
            }
            // Chunk on char boundaries so a surrogate pair is never split
            // across two keyboard events.
            let chars: Vec<char> = segment.chars().collect();
            for chunk in chars.chunks(12) {
                let units: Vec<u16> = chunk.iter().collect::<String>().encode_utf16().collect();
                Self::type_unicode(&units)?;
                std::thread::sleep(Duration::from_millis(8));
            }
        }
        Ok(())
    }

    fn key(&mut self, combo: &KeyCombo) -> Result<(), DriverError> {
        Self::require_accessibility()?;
        let (code, needs_shift) = keycode(&combo.key)?;
        let flags = modifier_flags(combo, needs_shift);
        Self::key_event(code, true, flags)?;
        std::thread::sleep(Duration::from_millis(20));
        Self::key_event(code, false, flags)
    }

    fn ui_tree(&mut self) -> Result<Vec<UiNode>, DriverError> {
        Err(DriverError::Unsupported(
            "UI tree dumps are only available on Android and HarmonyOS; use computer_zoom on macOS"
                .to_string(),
        ))
    }

    fn app(&mut self, action: AppAction<'_>) -> Result<String, DriverError> {
        let open = std::path::PathBuf::from("/usr/bin/open");
        let osascript = std::path::PathBuf::from("/usr/bin/osascript");
        match action {
            AppAction::Launch(name) => {
                let args: Vec<&str> = if name.contains('.') && !name.ends_with(".app") {
                    vec!["-b", name]
                } else {
                    vec!["-a", name]
                };
                process::run_ok(&open, &args, Duration::from_secs(20))?;
                Ok(format!("launched {name}"))
            }
            AppAction::List => {
                let out = process::run_ok(
                    &osascript,
                    &[
                        "-e",
                        "tell application \"System Events\" to get name of every process whose background only is false",
                    ],
                    Duration::from_secs(20),
                )?;
                let names: Vec<String> = out
                    .stdout_text()
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
                Ok(format!(
                    "{} running apps:\n{}",
                    names.len(),
                    names.join("\n")
                ))
            }
            AppAction::Current => {
                let out = process::run_ok(
                    &osascript,
                    &[
                        "-e",
                        "tell application \"System Events\" to get name of first process whose frontmost is true",
                    ],
                    Duration::from_secs(20),
                )?;
                Ok(format!("frontmost app: {}", out.stdout_text().trim()))
            }
        }
    }

    fn devices(&mut self) -> Result<String, DriverError> {
        Ok("desktop target (no adb/hdc device selected); set [android] or [harmony] in ~/.codewhale/computer-use.toml to drive a phone".to_string())
    }

    fn element(&mut self) -> Option<&mut dyn crate::elements::ElementDriver> {
        Some(self)
    }
}

