#[derive(Debug, Clone)]
pub struct AppSnapshot {
    pub identity: AppIdentity,
    pub window_w: u32,
    pub window_h: u32,
    pub image_w: u32,
    pub image_h: u32,
    pub node_count: usize,
}

impl AppSnapshot {
    /// Map window-image pixels to the window's own pixel space.
    pub fn to_window(&self, x: f64, y: f64) -> Result<(f64, f64), String> {
        let (w, h) = (f64::from(self.image_w.max(1)), f64::from(self.image_h.max(1)));
        if !x.is_finite() || !y.is_finite() || x < -0.5 || y < -0.5 || x > w + 0.5 || y > h + 0.5 {
            return Err(format!(
                "point ({x}, {y}) is outside the last app-state image {}x{}; call computer_app_state again",
                self.image_w, self.image_h
            ));
        }
        Ok((
            (x * f64::from(self.window_w) / w).clamp(0.0, f64::from(self.window_w.saturating_sub(1))),
            (y * f64::from(self.window_h) / h).clamp(0.0, f64::from(self.window_h.saturating_sub(1))),
        ))
    }
}

