fn drag_to_pid(
    pid: u32,
    from: (f64, f64),
    to: (f64, f64),
    duration_ms: u64,
) -> Result<(), DriverError> {
    mouse_to_pid(
        pid,
        K_CG_EVENT_LEFT_MOUSE_DOWN,
        from,
        K_CG_MOUSE_BUTTON_LEFT,
        1,
    )?;
    let steps = 20u64;
    let pause = duration_ms / steps;
    for step in 1..=steps {
        let f = step as f64 / steps as f64;
        let point = (from.0 + (to.0 - from.0) * f, from.1 + (to.1 - from.1) * f);
        mouse_to_pid(
