            window_id,
            K_CG_EVENT_LEFT_MOUSE_DRAGGED,
            point,
            K_CG_MOUSE_BUTTON_LEFT,
            1,
        )?;
        std::thread::sleep(Duration::from_millis(pause.max(5)));
    }
    mouse_to_pid(
        pid,
        window_id,
        K_CG_EVENT_LEFT_MOUSE_UP,
        to,
        K_CG_MOUSE_BUTTON_LEFT,
        1,
    )
}

